import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

conv_transpose2d_cuda_src = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void conv_transpose2d_kernel(
    const float* input,
    const float* weight,
    const float* bias,
    float* output,
    int N,
    int InC,
    int Hin,
    int Win,
    int OutC,
    int K,
    int Hout,
    int Wout,
    int stride,
    int padding,
    int dilation,
    bool has_bias
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * OutC * Hout * Wout;
    if (idx >= total) return;

    int n = idx / (OutC * Hout * Wout);
    int tmp = idx % (OutC * Hout * Wout);
    int oc = tmp / (Hout * Wout);
    tmp = tmp % (Hout * Wout);
    int oh = tmp / Wout;
    int ow = tmp % Wout;

    float val = 0.0f;
    for (int ic = 0; ic < InC; ic++) {
        for (int kh = 0; kh < K; kh++) {
            for (int kw = 0; kw < K; kw++) {
                int in_h = oh + padding - dilation * kh;
                int in_w = ow + padding - dilation * kw;
                if ((in_h % stride == 0) && (in_w % stride == 0)) {
                    int ih = in_h / stride;
                    int iw = in_w / stride;
                    if (ih >= 0 && ih < Hin && iw >= 0 && iw < Win) {
                        int input_idx = ((n * InC + ic) * Hin + ih) * Win + iw;
                        int weight_idx = ((oc * InC + ic) * K + kh) * K + kw;
                        val += input[input_idx] * weight[weight_idx];
                    }
                }
            }
        }
    }

    if (has_bias) {
        val += bias[oc];
    }

    int out_idx = ((n * OutC + oc) * Hout + oh) * Wout + ow;
    output[out_idx] = val;
}

torch::Tensor conv_transpose2d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int dilation
) {
    int N = input.size(0);
    int InC = input.size(1);
    int Hin = input.size(2);
    int Win = input.size(3);
    int OutC = weight.size(0);
    int K = weight.size(2);

    // Compute output height/width (transposed conv formula)
    int Hout = (Hin - 1) * stride - 2 * padding + dilation * (K - 1) + 1;
    int Wout = (Win - 1) * stride - 2 * padding + dilation * (K - 1) + 1;

    auto options = input.options();
    auto output = torch::zeros({N, OutC, Hout, Wout}, options);

    int total = N * OutC * Hout * Wout;
    const int blockSize = 256;
    int gridSize = (total + blockSize - 1) / blockSize;

    bool has_bias = (bias.numel() > 0);

    conv_transpose2d_kernel<<<gridSize, blockSize>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        has_bias ? bias.data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        N,
        InC,
        Hin,
        Win,
        OutC,
        K,
        Hout,
        Wout,
        stride,
        padding,
        dilation,
        has_bias
    );
    return output;
}
'''

conv_transpose2d_cpp_src = r'''
torch::Tensor conv_transpose2d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int dilation
);
'''

conv_transpose2d_extension = load_inline(
    name="custom_conv_transpose2d",
    cpp_sources=conv_transpose2d_cpp_src,
    cuda_sources=conv_transpose2d_cuda_src,
    functions=["conv_transpose2d_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    """
    Optimized Model with a custom CUDA kernel for transposed convolution.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, dilation: int = 1, bias: bool = False):
        super().__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation

        weight_shape = (out_channels, in_channels, kernel_size, kernel_size)
        self.weight = nn.Parameter(torch.randn(weight_shape))
        self.bias = nn.Parameter(torch.randn(out_channels)) if bias else None

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return conv_transpose2d_extension.conv_transpose2d_cuda(
            x,
            self.weight,
            self.bias if self.bias is not None else torch.tensor([], device=x.device),
            self.stride,
            self.padding,
            self.dilation
        )
